end
-- StmtChecker:239
function StmtChecker.check_loop(self, stmt, scope, frame)
    -- StmtChecker:240
    StmtChecker.check_block(self, stmt:child("body"), scope:child(), frame:in_loop_body())
end
-- StmtChecker:246
